Here is an example of how to implement this:

```python
from collections import namedtuple
import jax
import jax.numpy as jnp
from jax.experimental.hijax import HiPrim, Zero, instantiate_zeros

Point = namedtuple("Point", ["x", "y"])

class FPt(HiPrim):
  def __init__(self, pt_aval):
    self.in_avals = (pt_aval,)
    self.out_aval = {'a': pt_aval.x, 'b': (pt_aval.x, pt_aval.y)}
    self.params = {}
    super().__init__()

  def expand(self, pt):
    return {'a': pt.x ** 2, 'b': (jnp.sin(pt.x), jnp.cos(pt.y))}

  def vjp_fwd(self, nzs_in, pt):
    return self(pt), pt

  def vjp_bwd_retval(self, pt, g):
    g = jax.tree.map(instantiate_zeros, g,
                     is_leaf=lambda x: isinstance(x, Zero))
    a_bar, (b0_bar, b1_bar) = g['a'], g['b']
    x_bar = 2 * pt.x * a_bar + jnp.cos(pt.x) * b0_bar
    y_bar = -jnp.sin(pt.y) * b1_bar
    return (Point(x_bar, y_bar),)

def f(pt):
  return FPt(jax.tree.map(jax.typeof, pt))(pt)

def fun(pt):
  dct = f(pt)
  return dct['a'] + dct['b'][0]

pt = Point(1., 2.)
print(f(pt))
print(jax.grad(fun)(pt))
```

In this example:
- `FPt` is a custom primitive that defines the forward computation (`expand`) and the VJP rules (`vjp_fwd` and `vjp_bwd_retval`).
- The `vjp_fwd` method computes the forward pass and saves the input for the backward pass.
- The `vjp_bwd_retval` method computes the gradients with respect to the inputs using the saved input and the gradients from the output.

